use crate::usrmarshal::{Hresult, S_FALSE, S_OK};

/// `DllCanUnloadNow`, generated by the `DLLCANUNLOADNOW` macro in `include/rpcproxy.h`. It returns
/// `NdrDllCanUnloadNow(&gPFactory)` from `dlls/rpcrt4/cpsf.c`, which is `S_FALSE` while the
/// factory's `RefCount` is nonzero. `ref_count` is that `RefCount`.
pub fn dll_can_unload_now(ref_count: i32) -> Hresult {
    if ref_count != 0 {
        S_FALSE
    } else {
        S_OK
    }
}
